# Plays generated test tones through SDL's disk audio driver and checks what actually came out: the pitch (by counting
# zero crossings), that a looped sound keeps playing without gaps, and that SoundPitch and ChannelPitch are in Hz.
# Usage: audio_output.py <blitzcc> <work directory>. Skipped (77) when the disk driver is not available.
import math
import os
import struct
import subprocess
import sys
import wave

blitzcc, work = sys.argv[1:3]
os.makedirs(work, exist_ok=True)
os.chdir(work)

OUTPUT_RATE = 44100  # What the disk driver is fixed to.
CYCLE = 50  # Samples of a period of the tone, so that the tone is a whole number of cycles and a loop has no seam.


def tone(name, rate, channels, bits, cycles=40):
	with wave.open(name, "wb") as out:
		out.setnchannels(channels)
		out.setsampwidth(bits // 8)
		out.setframerate(rate)
		frames = bytearray()
		for i in range(CYCLE * cycles):
			v = math.sin(2 * math.pi * i / CYCLE)
			frames += (struct.pack("B", int(128 + v * 100)) if bits == 8 else struct.pack("<h", int(v * 8000))) * channels
		out.writeframes(bytes(frames))
	return rate / CYCLE


def play(name, setup="", after="", loop=True, milliseconds=1500):
	"""Plays a file and returns the left channel of what was sent to the disk driver."""
	with open("play.bb", "w") as source:
		source.write('s = LoadSound("%s")\n%s\n%s\nc = PlaySound(s)\n%s\nDelay %d\nDebugLog "playing " + ChannelPlaying(c)\n' % (name, "LoopSound s" if loop else "", setup, after, milliseconds))
	if subprocess.run([blitzcc, "play.bb", "-o", "play"], capture_output=True).returncode != 0:
		raise SystemExit("compiling failed")
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	run = subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	if not os.path.exists("sdlaudio.raw"):
		print("no disk audio driver")
		raise SystemExit(77)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	samples = list(struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2])
	return samples, run.stderr.decode(errors="replace")


failures = []


def check(what, condition):
	print(("ok   " if condition else "FAIL ") + what)
	if not condition:
		failures.append(what)


def analyze(samples):
	loud = [i for i, v in enumerate(samples) if abs(v) > 300]
	if not loud:
		return 0.0, 0.0, 0
	segment = samples[loud[0] + 4000 : loud[0] + 34000]
	crossings = [i for i in range(1, len(segment)) if segment[i - 1] < 0 <= segment[i]]
	frequency = OUTPUT_RATE * (len(crossings) - 1) / (crossings[-1] - crossings[0]) if len(crossings) > 2 else 0.0
	# A gap or a click is a jump the smooth tone does not have.
	d2 = [abs(segment[i + 1] - 2 * segment[i] + segment[i - 1]) for i in range(1, len(segment) - 1)]
	smoothness = max(d2) / max(1, sorted(d2)[len(d2) // 2])
	return frequency, smoothness, (loud[-1] - loud[0]) / OUTPUT_RATE


# Pitch of every kind of file, and that looping keeps it going for longer than the file is.
for rate in (8000, 11025, 22050, 44100, 48000):
	for channels in (1, 2):
		for bits in (8, 16):
			expected = tone("tone.wav", rate, channels, bits)
			samples, log = play("tone.wav")
			frequency, smoothness, length = analyze(samples)
			label = "%d Hz %d channel(s) %d bit" % (rate, channels, bits)
			check("%s: pitch %.1f Hz is %.1f Hz" % (label, frequency, expected), abs(frequency - expected) < expected * 0.01)
			check("%s: looped for %.2f s of a 0.09 s file" % (label, length), length > 1.0 and "playing 1" in log)
			check("%s: loop is gapless (jump %.1fx)" % (label, smoothness), smoothness < 4.0)

# The same file without looping ends by itself.
expected = tone("tone.wav", 22050, 1, 16)
samples, log = play("tone.wav", loop=False)
frequency, smoothness, length = analyze(samples)
check("one shot ends after %.2f s" % length, length < 0.5 and "playing 0" in log)

# SoundPitch and ChannelPitch are the frequency in Hz that the file is played at.
tone("tone.wav", 22050, 1, 16)
for what, setup, after, expected in (
	("SoundPitch 44100", "SoundPitch s, 44100", "", 882.0),
	("SoundPitch 11025", "SoundPitch s, 11025", "", 220.5),
	("ChannelPitch 44100", "", "ChannelPitch c, 44100", 882.0),
	("ChannelPitch 11025", "", "ChannelPitch c, 11025", 220.5),
):
	samples, log = play("tone.wav", setup, after)
	frequency, smoothness, length = analyze(samples)
	check("%s: pitch %.1f Hz is %.1f Hz" % (what, frequency, expected), abs(frequency - expected) < expected * 0.01)

sys.exit(1 if failures else 0)
